Class Card
  Define balance As Integer;
EndClass

Algorithm Canteen
  Define initial, amount As Integer;
  Read initial;
  Read amount;
  Define card As Card <- New Card();
  card.balance <- initial;
  If amount > 0 And amount <= card.balance Then
    card.balance <- card.balance - amount;
  EndIf
  Write card.balance;
EndAlgorithm

