Class Card
  Private Define balance As Integer;

  Method Constructor(initial As Integer)
    This.balance <- 0;
    If initial > 0 Then
      This.balance <- initial;
    EndIf
  EndMethod

  Method Charge(amount As Integer) As Boolean
    If amount <= 0 Or amount > This.balance Then
      Return False;
    EndIf
    This.balance <- This.balance - amount;
    Return True;
  EndMethod

  Method Load(amount As Integer) As Boolean
    If amount <= 0 Then
      Return False;
    EndIf
    This.balance <- This.balance + amount;
    Return True;
  EndMethod

  Method Balance() As Integer
    Return This.balance;
  EndMethod
EndClass

Algorithm Canteen
  Define initial, amount As Integer;
  Read initial;
  Read amount;
  Define card As Card <- New Card(initial);
  Define charged As Boolean <- card.Charge(amount);
  Write card.Balance();
EndAlgorithm
